def effective_limit(value, default=10):
    if value is None:
        # None means use the default
        return default
    if isinstance(value, int):
        if value == 0:
            # zero means disabled and must stay zero
            return 0
        if value < 0:
            # negative int raises ValueError
            raise ValueError('negative effective_limit not allowed')
        # positive int overrides default
        return value
    # if value is not an int (e.g., other type), we could raise or fallback; 
    # but signature says value is presumably int or None, so we keep simple
    # fallback: if value is truthy but not int, treat as overridden? spec only mentions ints and None.
    # We'll raise if unexpected type to be safe.
    raise TypeError('effective_limit value must be int or None')
